import { NextRequest, NextResponse } from "next/server";
import fs from "fs";
import path from "path";

const TODO_FILE = path.join(process.cwd(), "todos.md");

interface Todo {
  id: string;
  text: string;
  done: boolean;
  createdAt: string;
}

function parseTodos(): Todo[] {
  if (!fs.existsSync(TODO_FILE)) return [];
  const content = fs.readFileSync(TODO_FILE, "utf-8");
  const todos: Todo[] = [];

  for (const line of content.split("\n")) {
    const match = line.match(/^- \[(x| )\] (.+?) <!-- id:(.+?) createdAt:(.+?) -->$/);
    if (match) {
      todos.push({
        done: match[1] === "x",
        text: match[2],
        id: match[3],
        createdAt: match[4],
      });
    }
  }
  return todos;
}

function writeTodos(todos: Todo[]) {
  const lines = [
    "# Todos",
    "",
    ...todos.map(
      (t) =>
        `- [${t.done ? "x" : " "}] ${t.text} <!-- id:${t.id} createdAt:${t.createdAt} -->`
    ),
  ];
  fs.writeFileSync(TODO_FILE, lines.join("\n") + "\n", "utf-8");
}

export async function GET() {
  return NextResponse.json(parseTodos());
}

export async function POST(req: NextRequest) {
  const { text } = await req.json();
  if (!text?.trim()) return NextResponse.json({ error: "Empty todo" }, { status: 400 });
  const todos = parseTodos();
  const todo: Todo = {
    id: Date.now().toString(),
    text: text.trim(),
    done: false,
    createdAt: new Date().toISOString(),
  };
  todos.push(todo);
  writeTodos(todos);
  return NextResponse.json(todo, { status: 201 });
}

export async function PATCH(req: NextRequest) {
  const { id, done, text } = await req.json();
  const todos = parseTodos();
  const todo = todos.find((t) => t.id === id);
  if (!todo) return NextResponse.json({ error: "Not found" }, { status: 404 });
  if (done !== undefined) todo.done = done;
  if (text !== undefined) todo.text = text.trim();
  writeTodos(todos);
  return NextResponse.json(todo);
}

export async function DELETE(req: NextRequest) {
  const { id } = await req.json();
  const todos = parseTodos().filter((t) => t.id !== id);
  writeTodos(todos);
  return NextResponse.json({ ok: true });
}

