"use client";

import { useEffect, useRef, useState } from "react";

interface Todo {
  id: string;
  text: string;
  done: boolean;
  createdAt: string;
}

type Filter = "all" | "active" | "done";

export default function Home() {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [input, setInput] = useState("");
  const [filter, setFilter] = useState<Filter>("all");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editText, setEditText] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    fetch("/api/todos")
      .then((r) => r.json())
      .then(setTodos);
  }, []);

  async function addTodo(e: React.FormEvent) {
    e.preventDefault();
    if (!input.trim()) return;
    const res = await fetch("/api/todos", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ text: input }),
    });
    const todo = await res.json();
    setTodos((prev) => [...prev, todo]);
    setInput("");
  }

  async function toggle(todo: Todo) {
    const res = await fetch("/api/todos", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ id: todo.id, done: !todo.done }),
    });
    const updated = await res.json();
    setTodos((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
  }

  async function deleteTodo(id: string) {
    await fetch("/api/todos", {
      method: "DELETE",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ id }),
    });
    setTodos((prev) => prev.filter((t) => t.id !== id));
  }

  async function saveEdit(id: string) {
    if (!editText.trim()) return;
    const res = await fetch("/api/todos", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ id, text: editText }),
    });
    const updated = await res.json();
    setTodos((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
    setEditingId(null);
  }

  function startEdit(todo: Todo) {
    setEditingId(todo.id);
    setEditText(todo.text);
  }

  const filtered = todos.filter((t) => {
    if (filter === "active") return !t.done;
    if (filter === "done") return t.done;
    return true;
  });

  const activeCount = todos.filter((t) => !t.done).length;

  return (
    <main className="min-h-screen bg-zinc-950 text-zinc-100 flex flex-col items-center pt-20 px-4">
      <div className="w-full max-w-lg">
        <h1 className="text-3xl font-semibold tracking-tight mb-8 text-white">todos</h1>

        <form onSubmit={addTodo} className="flex gap-2 mb-6">
          <input
            ref={inputRef}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="What needs to be done?"
            className="flex-1 bg-zinc-900 border border-zinc-700 rounded-lg px-4 py-2.5 text-sm placeholder:text-zinc-500 focus:outline-none focus:border-zinc-500"
          />
          <button
            type="submit"
            className="bg-zinc-100 text-zinc-900 rounded-lg px-4 py-2.5 text-sm font-medium hover:bg-white transition-colors"
          >
            Add
          </button>
        </form>

        {todos.length > 0 && (
          <div className="flex gap-3 mb-4 text-xs text-zinc-500">
            {(["all", "active", "done"] as Filter[]).map((f) => (
              <button
                key={f}
                onClick={() => setFilter(f)}
                className={`capitalize transition-colors ${
                  filter === f ? "text-zinc-100" : "hover:text-zinc-300"
                }`}
              >
                {f}
              </button>
            ))}
            <span className="ml-auto">{activeCount} left</span>
          </div>
        )}

        <ul className="space-y-1">
          {filtered.map((todo) => (
            <li
              key={todo.id}
              className="group flex items-center gap-3 bg-zinc-900 border border-zinc-800 rounded-lg px-4 py-3 hover:border-zinc-700 transition-colors"
            >
              <button
                onClick={() => toggle(todo)}
                className={`w-4 h-4 rounded-full border flex-shrink-0 transition-colors ${
                  todo.done
                    ? "bg-zinc-400 border-zinc-400"
                    : "border-zinc-600 hover:border-zinc-400"
                }`}
              />

              {editingId === todo.id ? (
                <input
                  autoFocus
                  value={editText}
                  onChange={(e) => setEditText(e.target.value)}
                  onBlur={() => saveEdit(todo.id)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") saveEdit(todo.id);
                    if (e.key === "Escape") setEditingId(null);
                  }}
                  className="flex-1 bg-transparent text-sm focus:outline-none border-b border-zinc-600"
                />
              ) : (
                <span
                  onDoubleClick={() => startEdit(todo)}
                  className={`flex-1 text-sm cursor-default select-none ${
                    todo.done ? "line-through text-zinc-500" : ""
                  }`}
                >
                  {todo.text}
                </span>
              )}

              <button
                onClick={() => deleteTodo(todo.id)}
                className="opacity-0 group-hover:opacity-100 text-zinc-600 hover:text-red-400 transition-all text-lg leading-none"
              >
                ×
              </button>
            </li>
          ))}
        </ul>

        {filtered.length === 0 && (
          <p className="text-center text-zinc-600 text-sm mt-12">
            {filter === "done" ? "Nothing done yet." : filter === "active" ? "All caught up." : "No todos yet."}
          </p>
        )}

        {todos.length > 0 && (
          <p className="text-xs text-zinc-700 mt-6 text-center">
            Saved to <code className="text-zinc-600">todos.md</code>
          </p>
        )}
      </div>
    </main>
  );
}

